    private async Task LoadInitialData()
    {
        try
        {
            maTruongBo = await BrowserStorageService.GetMaTruongBoAsync(JS);
            selectedCapHoc = await BrowserStorageService.GetItem(JS, "selectedLevel") ?? "02";
            selectedNamHoc = await BrowserStorageService.GetItem(JS, "selectedNamHoc") ?? "2025-2026";

            // Đọc học kỳ từ session (lưu bởi TopNavbar)
            var hocKyStr = await BrowserStorageService.GetItem(JS, "selectedHocKy");
            if (!string.IsNullOrEmpty(hocKyStr) && int.TryParse(hocKyStr, out var savedHocKy))
                selectedHocKy = savedHocKy.ToString();
            else
                selectedHocKy = (DateTime.Now.Month >= 8 && DateTime.Now.Month <= 12) ? "1" : "2";

            if (string.IsNullOrEmpty(maTruongBo))
            {
                await JS.InvokeVoidAsync("alert", "Không tìm thấy mã trường. Vui lòng đăng nhập lại.");
                Nav.NavigateTo("/");
                return;
            }

            await LoadData();
        }
        catch (Exception ex)
        {
            await JS.InvokeVoidAsync("alert", "Đã xảy ra lỗi hệ thống, vui lòng thử lại!");
        }
    }

    private async Task LoadData()
    {
        isLoading = true;
        StateHasChanged();

        try
        {
            originalData = await DiemService.hGetKhoaSoDiem(
                selectedCapHoc!,
                maTruongBo!,
                selectedNamHoc!,
                Convert.ToInt32(selectedHocKy)
            );

            var lopHocs = await TruongService.hGetDanhSachLop(
                maTruongBo!,
                selectedCapHoc!,
                selectedNamHoc!
            );

            var khoiHocs = await TruongService.hGetDanhSachKhoi(
                maTruongBo!,
                selectedCapHoc!
            );

            BuildTreeStructure(originalData, lopHocs, khoiHocs);

            if (grades.Any() && grades.First().Classes.Any())
            {
                await SelectClass(grades.First().Classes.First(), grades.First());
            }
            else
            {
                selectedClass = null;
                subjects.Clear();
            }
        }
        catch (Exception ex)
        {
            await JS.InvokeVoidAsync("alert", "Đã xảy ra lỗi hệ thống, vui lòng thử lại!");
        }
        finally
        {
            isLoading = false;
            StateHasChanged();
        }
    }

    private void BuildTreeStructure(
        List<M_QLKhoaSoDiemDTO> khoaSoData,
        List<LopHoc_DTO> lopHocs,
        List<KhoiHoc_DTO> khoiHocs)
    {
        grades.Clear();

        var khoiGroups = khoiHocs.GroupJoin(
            lopHocs,
            k => k.MaKhoiBo,
            l => l.MaKhoiBo,
            (k, lopList) => new { Khoi = k, LopList = lopList.ToList() }
        );

        foreach (var khoiGroup in khoiGroups)
        {
            var grade = new GradeModel
            {
                MaKhoiBo = khoiGroup.Khoi.MaKhoiBo,
                Name = khoiGroup.Khoi.TenKhoi
            };

            foreach (var lop in khoiGroup.LopList)
            {
                var classModel = new ClassModel
                {
                    IdLopBo = lop.IdLopBo.ToString(),
                    MaKhoiBo = lop.MaKhoiBo,
                    Name = lop.TenLop,
                    TenLop = lop.TenLop,
                    GradeName = khoiGroup.Khoi.TenKhoi
                };

                var subjectsForClass = khoaSoData
                    .Where(x => x.IdLopBo == lop.IdLopBo.ToString())
                    .ToList();

                foreach (var subjectData in subjectsForClass)
                {
                    var subject = new SubjectModel
                    {
                        IdMonHoc = subjectData.IdMonHoc,
                        Name = subjectData.TenMonHoc,
                        IsLocked = subjectData.IsLock,
                        OriginalLocked = subjectData.IsLock,
                        LockedAt = subjectData.CreateUpdate,
                        StudentCount = new Random().Next(20, 45)
                    };
                    classModel.Subjects.Add(subject);
                }

                grade.Classes.Add(classModel);
            }

            grades.Add(grade);
        }
    }

    private async Task SelectClass(ClassModel cls, GradeModel grade)
    {
        selectedClass = cls;
        await LoadSubjectsForClass(cls.IdLopBo, grade.MaKhoiBo);
        StateHasChanged();
    }

    private async Task LoadSubjectsForClass(string idLopBo, string maKhoiBo)
    {
        if (string.IsNullOrEmpty(idLopBo) || originalData == null) return;

        isLoadingSubjects = true;
        StateHasChanged();

        try
        {
            subjects = originalData
                .Where(x => x.IdLopBo == idLopBo)
                .Select(x => new SubjectModel
                {
                    IdMonHoc = x.IdMonHoc,
                    Name = x.TenMonHoc,
                    IsLocked = x.IsLock,
                    OriginalLocked = x.IsLock,
                    LockedAt = x.CreateUpdate,
                    StudentCount = new Random().Next(20, 45),
                    TotalScores = 0,
                    FilledScores = 0
                })
                .ToList();

            foreach (var subject in subjects)
            {
                subject.TotalScores = subject.StudentCount * 5;
                subject.FilledScores = (int)(subject.TotalScores * (subject.IsLocked ? 1 : 0.8));
            }

            lastUpdate = subjects.Max(s => s.LockedAt);
            CheckUnsavedChanges();
        }
        catch (Exception ex)
        {
            await JS.InvokeVoidAsync("alert", "Đã xảy ra lỗi hệ thống, vui lòng thử lại!");
        }
        finally
        {
            isLoadingSubjects = false;
            StateHasChanged();
        }
    }

    private async Task ReloadSubjects()
    {
        if (selectedClass != null)
        {
            await LoadSubjectsForClass(selectedClass.IdLopBo, selectedClass.MaKhoiBo);
        }
    }

    // --- ACTIONS ---
    private void ToggleGrade(GradeModel grade)
    {
        grade.IsExpanded = !grade.IsExpanded;
        StateHasChanged();
    }

    private void ToggleSubject(SubjectModel subject)
    {
        if (subject.IsLocked)
        {
            confirmSubject = subject;
            confirmSubjectName = subject.Name;
            confirmAction = "unlock";
            showConfirmModal = true;
        }
        else
        {
            confirmSubject = subject;
            confirmSubjectName = subject.Name;
            confirmAction = "lock";
            showConfirmModal = true;
        }
        StateHasChanged();
    }

    private async Task ConfirmToggle()
    {
        if (confirmSubject != null)
        {
            bool newLockState = confirmAction == "lock";
            confirmSubject.IsLocked = newLockState;
            confirmSubject.LockedAt = DateTime.Now;

            if (selectedClass != null)
            {
                var classSubject = selectedClass.Subjects
                    .FirstOrDefault(s => s.IdMonHoc == confirmSubject.IdMonHoc);
                if (classSubject != null)
                {
                    classSubject.IsLocked = newLockState;
                    classSubject.LockedAt = DateTime.Now;
                }
            }

            CheckUnsavedChanges();
            CloseConfirmModal();
            StateHasChanged();

            await ShowToast(
                $"Đã {(newLockState ? "khóa" : "mở")} sổ điểm môn {confirmSubjectName}",
                newLockState ? "warning" : "success");
        }
    }

    private void ToggleAllSubjects(bool lockAll)
    {
        bulkActionIsLock = lockAll;
        showBulkConfirmModal = true;
        StateHasChanged();
    }

    private async Task ConfirmBulkToggle()
    {
        if (selectedClass != null)
        {
            foreach (var subject in subjects)
            {
                subject.IsLocked = bulkActionIsLock;
                subject.LockedAt = bulkActionIsLock ? DateTime.Now : (DateTime?)null;

                var classSubject = selectedClass.Subjects
                    .FirstOrDefault(s => s.IdMonHoc == subject.IdMonHoc);
                if (classSubject != null)
                {
                    classSubject.IsLocked = bulkActionIsLock;
                    classSubject.LockedAt = bulkActionIsLock ? DateTime.Now : (DateTime?)null;
                }
            }

            CheckUnsavedChanges();
            CloseBulkConfirmModal();
            StateHasChanged();

            await ShowToast(
                $"Đã {(bulkActionIsLock ? "khóa" : "mở")} tất cả {subjects.Count} môn học",
                bulkActionIsLock ? "warning" : "success");
        }
    }

    private async Task SaveAllChanges()
    {
        if (selectedClass == null || !hasUnsavedChanges) return;

        isSaving = true;
        StateHasChanged();

        try
        {
            var changedSubjects = subjects.Where(s => s.HasChanges).ToList();
            int savedCount = 0;

            foreach (var subject in changedSubjects)
            {
                var dto = new M_QLKhoaSoDiemDTO
                {
                    IdLopBo = selectedClass.IdLopBo,
                    IdMonHoc = subject.IdMonHoc,
                    TenMonHoc = subject.Name,
                    Cap = selectedCapHoc!,
                    MaTruongBo = maTruongBo!,
                    IsLock = subject.IsLocked,
                    TenKhoi = selectedClass.GradeName,
                    TenLop = selectedClass.Name,
                    HocKy = Convert.ToInt32(selectedHocKy),
                    NamHoc = selectedNamHoc
                };

                await DiemService.hUpsertKhoaSoDiem(dto);

                subject.OriginalLocked = subject.IsLocked;
                subject.LockedAt = subject.IsLocked ? DateTime.Now : (DateTime?)null;

                savedCount++;
            }

            lastUpdate = DateTime.Now;
            CheckUnsavedChanges();
            await ShowToast($"Đã lưu {savedCount} thay đổi thành công", "success");
        }
        catch (Exception ex)
        {
            await JS.InvokeVoidAsync("alert", "Đã xảy ra lỗi hệ thống, vui lòng thử lại!");
        }
        finally
        {
            isSaving = false;
            StateHasChanged();
        }
    }

    // --- HELPER METHODS ---
    private void CheckUnsavedChanges()
    {
        unsavedCount = subjects.Count(s => s.HasChanges);
        hasUnsavedChanges = unsavedCount > 0;

        if (selectedClass != null)
        {
            selectedClass.Subjects = subjects;
        }
    }

    private string GetClassIcon(bool isLocked)
    {
        return isLocked ? "fa-lock" : "fa-folder-open";
    }

    private string GetOverallStatusClass()
    {
        if (subjects.Count == 0) return "chkd-neutral";
        if (subjects.All(s => s.IsLocked)) return "chkd-locked";
        if (subjects.All(s => !s.IsLocked)) return "chkd-unlocked";
        return "chkd-partial";
    }

    private string GetOverallStatusText()
    {
        if (subjects.Count == 0) return "Chưa có dữ liệu";
        int lockedCount = subjects.Count(s => s.IsLocked);
        if (lockedCount == subjects.Count) return "Đã khóa toàn bộ";
        if (lockedCount == 0) return "Đang mở toàn bộ";
        return $"Đã khóa {lockedCount}/{subjects.Count} môn";
    }

