    // --- COPY CONFIG ---
    private void ShowCopyModal()
    {
        copyTargetClasses.Clear();
        copyMode = "class";
        copyOnlyLockState = false;
        showCopyModal = true;
        StateHasChanged();
    }

    private void CloseCopyModal()
    {
