    }

    private void ToggleCopyTarget(string idLopBo)
    {
        if (copyTargetClasses.Contains(idLopBo))
            copyTargetClasses.Remove(idLopBo);
        else
            copyTargetClasses.Add(idLopBo);
        StateHasChanged();
    }

    private List<ClassModel> GetSameGradeClasses()
    {
        if (selectedClass == null) return new();
        return grades
            .FirstOrDefault(g => g.MaKhoiBo == selectedClass.MaKhoiBo)
            ?.Classes
            .Where(c => c.IdLopBo != selectedClass.IdLopBo)
            .ToList() ?? new();
    }

    private async Task ExecuteCopy()
    {
        if (selectedClass == null || subjects.Count == 0) return;

        List<string> targetIds;
        if (copyMode == "grade")
            targetIds = GetSameGradeClasses().Select(c => c.IdLopBo).ToList();
        else
            targetIds = copyTargetClasses.ToList();

        if (!targetIds.Any())
        {
            await ShowToast("Vui lòng chọn ít nhất một lớp đích.", "warning");
            return;
        }

        isCopying = true;
        StateHasChanged();

        int successCount = 0;
        int errorCount = 0;

        try
        {
            foreach (var targetId in targetIds)
            {
                ClassModel? targetClass = null;
                GradeModel? targetGrade = null;
                foreach (var g in grades)
                {
                    var c = g.Classes.FirstOrDefault(x => x.IdLopBo == targetId);
                    if (c != null) { targetClass = c; targetGrade = g; break; }
                }
                if (targetClass == null) continue;

                var targetExistingSubjects = originalData?
                    .Where(x => x.IdLopBo == targetId)
                    .ToDictionary(x => x.IdMonHoc) ?? new();

                foreach (var srcSubject in subjects)
                {
                    try
                    {
                        if (copyOnlyLockState && !targetExistingSubjects.ContainsKey(srcSubject.IdMonHoc))
                            continue;

                        var dto = new M_QLKhoaSoDiemDTO
                        {
                            IdLopBo = targetId,
                            IdMonHoc = srcSubject.IdMonHoc,
                            TenMonHoc = srcSubject.Name,
                            Cap = selectedCapHoc!,
                            MaTruongBo = maTruongBo!,
                            IsLock = srcSubject.IsLocked,
                            TenKhoi = targetClass.GradeName,
                            TenLop = targetClass.Name,
                            HocKy = Convert.ToInt32(selectedHocKy),
                            NamHoc = selectedNamHoc
                        };
                        await DiemService.hUpsertKhoaSoDiem(dto);
                    }
                    catch
                    {
                        errorCount++;
                    }
                }
                successCount++;
            }

            await LoadData();
            CloseCopyModal();

            if (errorCount == 0)
                await ShowToast($"Đã sao chép thành công vào {successCount} lớp!", "success");
            else
                await ShowToast($"Copy xong: {successCount} lớp, {errorCount} lỗi.", "warning");
        }
        catch (Exception ex)
        {
            Console.WriteLine(ex);
            await ShowToast("Đã xảy ra lỗi, vui lòng thử lại!", "error");
        }
        finally
        {
            isCopying = false;
            StateHasChanged();
        }
    }

    // --- EVENT HANDLERS FOR YEAR & SEMESTER ---
    private async Task OnNamHocChanged(ChangeEventArgs e)
    {
        selectedNamHoc = e.Value?.ToString();
        await LoadData();
    }

    private async Task OnHocKyChanged(ChangeEventArgs e)
    {
        selectedHocKy = e.Value?.ToString() ?? "1";
        await LoadData();
    }

    #region func hepler
    private async Task ShowToast(string message, string type = "info")
    {
        try
        {
            await JS.InvokeVoidAsync("showToast", message, type);
        }
        catch (JSException ex)
        {
            if (ex.Message.Contains("showToast"))
            {
                await JS.InvokeVoidAsync("alert", $"{GetTypeEmoji(type)} {message}");
            }
            else
            {
                throw;
            }
        }
    }

    private string GetTypeEmoji(string type)
    {
        return type switch
        {
            "success" => "✅",
            "error" => "❌",
            "warning" => "⚠️",
            _ => "ℹ️"
        };
    }
    #endregion

